using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Security.Cryptography;using System.Collections.Generic;using System.Web.Script.Serialization;
internal static class SensorProvider {
 internal static string Folder(string dataFolder){return Path.Combine(dataFolder,"components","LibreHardwareMonitor-v0.9.6");}
 internal static bool Running{get{var processes=Process.GetProcessesByName("LibreHardwareMonitor");bool running=processes.Length>0;foreach(var p in processes)p.Dispose();return running;}}
 sealed class Lease:IDisposable {internal readonly List<FileStream> Streams=new List<FileStream>();public void Dispose(){foreach(var f in Streams)f.Dispose();}}
 internal static IDisposable Verify(string folder){folder=QuotaExecutionTrust.LocalPath(folder);var lease=new Lease();try{Dictionary<string,string> expected;using(var resource=typeof(SensorProvider).Assembly.GetManifestResourceStream("Conan.SensorProviderHashes")){if(resource==null)throw new IOException("缺少官方温度组件校验清单。");using(var reader=new StreamReader(resource))expected=new JavaScriptSerializer().Deserialize<Dictionary<string,string>>(reader.ReadToEnd());}foreach(var item in expected){string path=Path.Combine(folder,item.Key.Replace('/',Path.DirectorySeparatorChar));if(!File.Exists(path)||(File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new IOException("温度组件缺失或使用链接，请重新安装官方v0.9.6便携包。");var f=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read);lease.Streams.Add(f);using(var sha=SHA256.Create())if(BitConverter.ToString(sha.ComputeHash(f)).Replace("-","").ToLowerInvariant()!=item.Value)throw new IOException("温度组件校验失败，已阻止启动："+item.Key);}var allowed=new HashSet<string>(expected.Keys.Select(x=>x.Replace('/',Path.DirectorySeparatorChar)),StringComparer.OrdinalIgnoreCase);foreach(string file in Directory.GetFiles(folder,"*",SearchOption.AllDirectories)){string relative=file.Substring(folder.Length+1);if((file.EndsWith(".exe",StringComparison.OrdinalIgnoreCase)||file.EndsWith(".dll",StringComparison.OrdinalIgnoreCase))&&!allowed.Contains(relative))throw new IOException("温度组件含额外可执行文件，请使用干净的官方便携包。");}return lease;}catch{lease.Dispose();throw;}}
 static string Quote(string value){return "'"+value.Replace("'","''")+"'";}
 internal static string Script(string folder){string template,hashes;using(var stream=typeof(SensorProvider).Assembly.GetManifestResourceStream("Conan.SensorBootstrap")){if(stream==null)throw new IOException("缺少内置温度启动器。");using(var reader=new StreamReader(stream))template=reader.ReadToEnd();}using(var stream=typeof(SensorProvider).Assembly.GetManifestResourceStream("Conan.SensorProviderHashes"))using(var reader=new StreamReader(stream))hashes=reader.ReadToEnd();var expected=new JavaScriptSerializer().Deserialize<Dictionary<string,string>>(hashes);return "$folder="+Quote(QuotaExecutionTrust.LocalPath(folder))+"\n$readerSid="+Quote(LocalProtection.User)+"\n$expected=@{"+String.Join(";",expected.Select(p=>Quote(p.Key)+"="+Quote(p.Value)).ToArray())+"}\n"+template;}
 internal static void Start(string dataFolder){string folder=Folder(dataFolder);if(!Directory.Exists(folder))throw new IOException("此账户尚未准备温度组件。请在“数据来源”查看官方接入说明。");using(Verify(folder)){}string script=Script(folder);var process=Process.Start(new ProcessStartInfo(LimiterSecurity.PowerShell,"-NoProfile -NonInteractive -EncodedCommand "+Convert.ToBase64String(System.Text.Encoding.Unicode.GetBytes(script))){UseShellExecute=true,Verb="runas",WorkingDirectory=Environment.GetFolderPath(Environment.SpecialFolder.System),WindowStyle=ProcessWindowStyle.Hidden});System.Threading.Tasks.Task.Run(()=>{try{process.WaitForExit();}finally{process.Dispose();}});}
}
